"""Generate the discussant report from completed estimates, without changing sources."""
import json, hashlib
from pathlib import Path
import numpy as np
import pandas as pd
from settings import OUT
from statistics_common import cell,markdown


def read(name):return pd.read_csv(OUT/'tables'/name)
def fmt(x):return 'NA' if pd.isna(x) else f'{x:.4f}'
def table(df):return markdown(df)+'\n\n'
def assessment(r):
    if pd.isna(r.p):return 'Not estimable; no support claim.'
    if r.p>=.1:return 'No statistically clear incremental association.'
    return 'Positive conditional association; supports incremental prediction in this specification.' if r.coefficient_D>0 else 'Negative conditional association; contrary to the proposed positive predictive channel.'

def run():
    sections=['''# Discussant analyses and replication audit — Counting the same cash

Prepared 18 October 2026. Source manuscript: **WKZhangKangRyuSun_Zhang_111_Sun.docx**. The manuscript was read only; reviewer annotations in the document were treated as evidence, not instructions. No manuscript estimate or wording was changed. Stars denote 10%, 5%, and 1% significance (*, **, ***); parentheses contain t statistics. Unrounded values, sample sizes and individual result assessments are retained below and in linked CSVs. These are descriptive conditional associations, not causal effects.

**Main findings.** D does not provide consistent incremental prediction of recorded errors beyond cash capacity and utilization. Some replay specifications are positive, but signs, significance and out-of-sample gains vary by horizon and model. Borrow-event arithmetic survives some dependence corrections, with substantially fewer effective market clusters than the requested 33. Withdrawal associations also appear at placebo hours and do not establish an event-specific response. Archived table values match the manuscript, but an independent boundary audit finds changes to the event censoring and isolation samples.

## 1. Incremental predictive information in duplication

**Sample and definitions.** The ten Base vaults provide 4,390 vault-days over 439 closes. Because a pool-wide joint bound has no unique allocation to individual vaults, the primary vault bound is the marginal joint contribution ΔJ_v = J(V) − J(V excluding v), divided by the vault's own assets. D_v = 1 − ΔJ_v / standalone capacity is the archived vault competing-cash measure, independently checked against positions and cash. A second specification uses pool-wide J divided by aggregate assets. This definition must be retained when interpreting the results; it is not an arbitrary allocation of the aggregate duplication rate.

M0 includes J/A, position-weighted market utilization, log assets, active market count and year-month fixed effects; M1 adds D. Full-sample future outcomes use dates t+1 through t+h, h=1,7,30: any recorded liquidity-error withdrawal/redemption call; any future initiated 25% replay request unpaid after 24 hours; and a future minimum marginal joint cash contribution below the vault's own median. Incomplete future windows are removed. The replay outcome is reconstructed for each vault from the actual payment queue, rather than copying an aggregate request outcome across vaults.

The two-way covariance uses vault and date CR1 components; t tests use 9 degrees of freedom. The within-vault Newey–West check uses Bartlett weights and max(7,h) calendar-day lags. Nonpositive two-way variances are not repaired. LPM reports R² after removing year-month mean outcome variation; logits report McFadden pseudo-R². Constant-outcome month strata are dropped identically from M0/M1 in the unpenalized fixed-effect logits; their counts are in the CSV. No penalized fallback is substituted.

### Full-sample results (all specifications)

Each line states whether that particular result supports incremental predictive information. LPM and logit coefficient scales differ. Use changes in R² and held-out AUC alongside significance.
''']
    d=read('incremental_prediction.csv')
    for basis,g in d.groupby('baseline',sort=False):
        for cov,z in g.groupby('covariance',sort=False):
            sections.append(f'#### {basis}; {cov}\n\n')
            rows=[]
            for r in z.itertuples():
                rows.append({'Outcome':r.outcome,'Days':r.h,'Model':r.model,'D coefficient (t)':cell(r.coefficient_D,r.t,r.p),'N':r.N,'ΔR²':fmt(r.delta_R2),'Assessment':assessment(r)})
            sections.append(table(pd.DataFrame(rows)))
    sections.append('### Chronological out-of-sample results\n\nThe first 300 dates end on 2025-11-11; all remaining usable dates form the test set. This is a single chronological holdout at the requested split, not a repeatedly expanding estimation window. Training labels are purged h days before the cutoff (h+1 for replay, which needs another 24 hours). Low-bound thresholds use training-only vault medians. A future unseen year-month uses the latest estimable training-month intercept. Error-event test positives are sparse, making AUC unstable; class counts are shown.\n\n')
    a=read('incremental_prediction_oos.csv');rows=[]
    for r in a.itertuples():rows.append({'JA':r.baseline,'Outcome':r.outcome,'h':r.h,'Model':r.model,'Test N':r.test_N,'Positive':r.test_positive,'AUC M0':fmt(r.AUC_M0),'AUC M1':fmt(r.AUC_M1),'ΔAUC':fmt(r.delta_AUC),'Assessment':'Held-out ranking improves.' if r.delta_AUC>0 else 'No held-out ranking improvement.'})
    sections.append(table(pd.DataFrame(rows)))
    sections.append('**Scope failure — four-chain daily extension.** The available four-chain vault-state panel has seven irregular census dates, rather than a daily panel with complete matched next-1/7/30-day errors and replay coverage. Those census intervals cannot substitute for the requested horizons. No comparable four-chain forward-outcome estimates are claimed. See [coverage](tables/four_chain_outcome_coverage.csv).\n\n**Assessment:** mixed replay associations and unstable error predictions do not establish a general informational advantage for D. Low-bound results share construction and persistence with the predictors and require especially cautious interpretation. All 72 coefficient/inference rows and 36 holdout comparisons are reported, including unfavorable findings.\n\n## 2. Large-borrow event study (current Table 8)\n\n### Re-estimation and dependence\n\nThe threshold is transaction-level borrowing greater than 10% of preceding-block market cash; events follow the archived 24-hour cooldown. The 33-market input panel supplies 834 main events from 30 markets. The complete duplication outcome sample has 651 events from 28 markets, rather than 33 nonempty estimation clusters. All nine horizon states must be defined before subsequent-borrow censoring. Column (3) includes centered vault-count × horizon interactions together with horizon main effects. Event fixed effects absorb event-level constants; −24 hours is the reference. Panel A is the change in duplication (fraction); Panel B is joint cash in millions of USDC.\n\nMarket and market/date covariances use CR1 and the smaller cluster count for reference degrees of freedom. Wild-cluster p-values use 999 null-imposed Rademacher market draws, seed 20261018, with a market-studentized statistic. Event effects nest within markets. Zero-event markets cannot count as effective clusters. Original event clustering is retained for direct manuscript comparison.\n\n')
    for panel in ['A','B']:
        for cov in ['event_original','market','market_date']:
            sections.append(f'### Panel {panel}: {cov}\n\n'+(OUT/f'tables/Table8_Panel_{panel}_{cov}.md').read_text()+'\n\n')
    b=read('table8_reestimated_unrounded.csv'); main=b[b['sample'].eq('main')]
    rows=[]
    for panel in ['A','B']:
        for col in range(1,5):
            z=main[(main.panel.eq(panel))&main.column.eq(col)&main.covariance.eq('market')]
            for r in z.itertuples():
                coef=getattr(r,'coefficient');sign=1 if panel=='A' else -1
                support='Direction consistent with the immediate cash channel.' if coef*sign>0 else 'Direction does not support the immediate cash channel.'
                if 'event' not in r.term:support='Horizon association; not a separate causal mechanism test.'
                rows.append({'Panel':panel,'Column':col,'Term':r.term,'Market-cluster estimate (t)':cell(coef,r.t,r.p),'Wild p (999)':fmt(r.wild_p_market),'Assessment':support+(' Wild p < .10.' if r.wild_p_market<.1 else ' Wild test not significant at 10%.')})
    sections.append('### Market wild-bootstrap inference and result assessments\n\n'+table(pd.DataFrame(rows)))
    sections.append('### Subsequent recorded cash flows\n\nThese cumulative outcomes start strictly after the event block and use the original column (2), Panel B complete-state sample and censoring convention: 834 events, 5,514 horizon observations before outcome-specific zero baseline rows. Flows are measured at the same observed horizon target blocks. Pre/event cumulative outcomes are zero by construction and are not interpreted as estimated leads. Net supply is recorded supplies minus withdrawals, separately for all participants and the ten sample vaults. Repayments are shown both excluding and including liquidation proceeds. Units: millions of USDC. Coefficients below retain the manuscript event-study horizon layout; all inference variants are in [unrounded flows](tables/postborrow_flow_estimates.csv).\n\n')
    f=read('postborrow_flow_estimates.csv');rows=[]
    for cov in ['market','market_date']:
        for outcome in f.outcome.unique():
            z=f[f.covariance.eq(cov)&f.outcome.eq(outcome)&f.term.isin(['h_p1','h_p6','h_p24','h_p72','h_p168'])]
            for r in z.itertuples():rows.append({'Covariance':cov,'Outcome':outcome,'Horizon':r.term,'Coefficient (t)':cell(r.coefficient,r.t,r.p),'Wild p':fmt(r.wild_p_market),'Assessment':('Positive recorded inflow response.' if r.coefficient>0 else 'No positive recorded inflow response.')+(' Statistically clear at 10%.' if r.p<.1 else ' Not clear at 10%.')})
    sections.append(table(pd.DataFrame(rows)))
    sections.append('### Event overlap and coverage correction\n\nThe original ledger-bounded selection reproduces the manuscript. Appending the independently reconstructed 21 qualifying borrows in the seven-day tail changes three next-borrow times. The old 80 isolated events include two events without a fully observed prior 168 hours. The coverage-certified sample therefore has 78 events. This is a detected sample-boundary error, not a change made to match desired estimates. Pre/event states are retained when the next borrow has the same timestamp, matching the manuscript convention; [same-timestamp cases](data/table8_same_timestamp_censor_boundary.csv) make this boundary explicit.\n\n')
    rows=[['Qualifying borrow within 24h',386,386],['Within 72h',547,548],['Within 168h',668,669],['Isolated events (Panel B)',80,78],['Censored N (Panel A)',4335,4333],['Censored N (Panel B)',5514,5512],['Censored 168h events (A)',130,129],['Censored 168h events (B)',166,165]]
    sections.append(table(pd.DataFrame(rows,columns=['Quantity','Archived / manuscript convention','Coverage corrected'])))
    corrected=read('table8_coverage_corrected_estimates.csv');rows=[]
    for panel in ['A','B']:
        for sample,oldsample in [('tail_completed_censored','main'),('coverage_certified_isolated','isolated168')]:
            old=b[b.panel.eq(panel)&b['sample'].eq(oldsample)&b.covariance.eq('event_original')]
            if oldsample=='main':old=old[old.column.eq(2)]
            new=corrected[corrected.panel.eq(panel)&corrected['sample'].eq(sample)&corrected.covariance.eq('event_original')]
            for r in new.itertuples():
                o=old[old.term.eq(r.term)].iloc[0]
                rows.append({'Panel':panel,'Sample':sample,'Term':r.term,'Old coefficient (t)':cell(o.coefficient,o.t,o.p),'New coefficient (t)':cell(r.coefficient,r.t,r.p),'Δ coefficient':f'{r.coefficient-o.coefficient:.10f}','Assessment':'Boundary correction; immediate direction retained.' if r.term=='h_event' else 'Reports sensitivity to the observed event window.'})
    sections.append(table(pd.DataFrame(rows)))
    sections.append('**Additional Table 8 note error:** the note attributes the 651-event sample to positive pre-event vault positions. All 834 events have at least one such vault; 651 instead reflects complete defined duplication outcomes at all nine states. This definition should be corrected in a future manuscript edit. No change was applied to the supplied Word file.\n\nPer-market overlap below uses the full tail; the original version is preserved in [original overlap CSV](tables/borrow_overlap_by_market.csv). Counts are on the common 834-event sample, including markets with zero retained events. The three aggregate overlap shares are 386/834, 548/834 and 669/834.\n\n')
    ov=read('borrow_overlap_by_market.csv');events=pd.read_csv(OUT/'data/table8_column2_event_list.csv');audit=pd.read_csv(OUT/'data/event_boundary_audit.csv');e=events.merge(audit,on='event_id',validate='one_to_one')
    for h in [24,72,168]:
        counts=(e.assign(flag=e.new_next_timestamp-e.timestamp<=h*3600).groupby('market').flag.sum())
        ov[f'next_within_{h}h_events']=ov.market.map(counts).fillna(0).astype(int)
        ov[f'next_within_{h}h_share']=ov[f'next_within_{h}h_events']/ov.events.replace(0,np.nan)
    ov.to_csv(OUT/'tables/borrow_overlap_full_tail.csv',index=False)
    display=ov[['market','events']].copy()
    for h in [24,72,168]:display[f'≤{h}h events / share']=[f'{n} / {fmt(p)}' for n,p in zip(ov[f'next_within_{h}h_events'],ov[f'next_within_{h}h_share'])]
    sections.append(table(display))
    sections.append('**Assessment:** the immediate signs agree with the cash-allocation mechanism in several dependence-adjusted specifications, but overlapping borrows, the reduced number of clusters and the coverage corrections limit a behavioral interpretation. Every horizon, placebo, bootstrap result and old/new correction is retained.\n\n## 3. Exploratory withdrawal spillovers\n\nA large withdrawal is gross recorded vault withdrawal/redemption during a fixed UTC clock hour divided by assets observed before that hour; thresholds are 2%, 5% and 10%. This is an hourly aggregation definition, not a rolling 60-minute scan. Follow-up begins after the trigger hour and covers the next 1,6,24,72 hours. Other vaults are classified by any common positive-position market, and a second regressor weights exposure by the receiver’s positions in the source vault’s markets. Event fixed effects absorb date fixed effects because each event occurs on one date. Covariances cluster on event date. The placebo draws random source-vault non-event hours below the 2% threshold in the same observed window, seed 20261018, with the same common positive-asset receiver cohort; placebo inference clusters on placebo dates. No outlier deletion or winsorization is applied.\n\nThe primary amount outcome is millions of USDC withdrawn by the receiver. The secondary outcome is withdrawal divided by receiver assets before the hour; very small initial assets can produce extreme ratios when new funds arrive later. Both are reported. Positive dollar-level differences can reflect receiver size and turnover, and the positive placebo results are a material countercheck. No actual-minus-placebo significance test is asserted.\n\n**Scope failure:** available pre-hour positions/assets cover two event windows (2–17 October and 27 October–21 November), not the full historical period. Ethereum includes the observed native-USDC V1 universe in those windows; Base contains the original ten-vault panel, not all 162 native-USDC V1 vaults. Full historical universe claims would require missing hourly portfolios and assets. Observations without full follow-up are excluded rather than set to zero. See [coverage](tables/withdrawal_scope_coverage.csv). This is an exploratory extension and must not be described as bank-run evidence.\n\n### All thresholds, exposure definitions and placebo results\n\n')
    s=read('withdrawal_spillover_estimates.csv')
    for outcome,z in s.groupby('outcome',sort=False):
        sections.append(f'#### Outcome: {outcome}\n\n');rows=[]
        for r in z.itertuples():
            assessment_text='Placebo association; weakens event-specific interpretation.' if r.kind=='placebo' and r.p<.1 else 'Placebo not statistically clear at 10%.' if r.kind=='placebo' else 'Positive conditional association; placebo comparison needed.' if r.coefficient>0 and r.p<.1 else 'No clear positive association.'
            rows.append({'Chain':{1:'Ethereum',8453:'Base (10 vaults)'}.get(r.chain,str(r.chain)),'Threshold':f'{100*r.threshold:g}%','Hours':r.h,'Type':r.kind,'Exposure':r.exposure,'Estimate (t)':cell(r.coefficient,r.t,r.p),'Events':r.events,'Date clusters':r.date_clusters,'Assessment':assessment_text})
        sections.append(table(pd.DataFrame(rows)))
    sections.append('**Assessment:** shared-market withdrawal amounts are positively associated in the main 5% specifications, but similarly positive placebo associations do not identify a withdrawal response triggered by the source event. The all-Base-universe extension remains incomplete.\n\n## 4. Replication gaps, manuscript checker and delivery\n\n### Runnable Table 8 column (2) and isolation selection\n\n[Portable Table 8 package](package/table8/README.md) contains the program, complete horizon panel, threshold candidates, event metadata, exact sample selection, unrounded expected and reproduced coefficients, an 80-event list, the separately certified 78-event list, boundary audit, pinned requirements and SHA-256 input manifest. Run from `package/table8`: `pip install -r requirements.txt` followed by `python code/reproduce.py`. Its log and cell checks are in `output/run.log` and `output/checks.csv`. This package reproduces the archived column (2) convention; coverage-corrected inference and full tail results are separately linked above.\n\n### Full 439-day recorded-operation replay\n\n[Portable full replay](package/full_replay/README.md) includes `code/analyze.py`, `code/run_all.py`, the ledger, seven-day tail, daily initial positions/states and market cash, exact requirements, and hashes. Run from that folder: `pip install -r requirements.txt` then `python code/run_all.py`. Paths within both packages are relative; no external-volume path or RPC access is needed. This is replay of recorded operations, with fixed requests/queue and capped cash outflows. All 439 dates × 3 request sizes × 2 ordering rules = 2,634 runs match archived outputs; cash comparisons use integer micro-USDC. The per-vault 24-hour payment labels contain 4,390 rows. See `output/replay_verification.csv`, `output/run_status.json` and `output/run.log`. Raw ledger inclusion makes this full bundle larger than the earlier small addon package; it is intentionally a full-replay deliverable.\n\n### Source map and Word checker\n\n[SOURCE_MAP.csv](SOURCE_MAP.csv) maps every current numbered table to result files and producing programs. Former review Table 10 is current Table 8, and former review Table 19 is current Table 11. The program-path audit is in [logs/source_map_program_audit.csv](logs/source_map_program_audit.csv). Source-root-relative entries refer to the original Replication_Package; discussant/project-relative entries are labeled separately.\n\nThe current-file read-only checker tests **614 mapped numeric cells across all 15 numbered tables, with zero differences against archived unrounded sources**. All displayed coefficient/value cells in Table 8 and C1 are included; coefficient/t cells are targeted in regression tables 3/4/7/B2. This is not a claim that every categorical label or ancillary N/R² outside Table 8 was independently re-estimated. The old checker hard-coded earlier Roman table numbering and paths; `code/04_word_checker.py` is the current-numbering adaptation. [Checks](tables/word_numeric_checks.csv), [differences](tables/word_numeric_differences.csv), [status](logs/word_checker_status.json).\n\nZero differences means the current document faithfully carries archived numbers. It does **not** negate the independently discovered event-boundary and Table 8 note errors above. Original and corrected numbers are both reported, and the manuscript hash is unchanged:\n\n`c21ed5d136e0997480584dc7a48c067344d4569bcfb1ef5d4de37a04495c965f`\n\n### Pass / partial / fail register\n\n')
    register=[['PASS','Ten-vault forward outcomes','All 4,390 days joined to individual replay labels; all models and unfavorable results saved.'],['PARTIAL','Chronological validation','Requested 300-date split implemented as one purged holdout; no repeated rolling refits.'],['FAIL / unavailable','Four-chain daily prediction','Seven irregular censuses cannot support comparable 1/7/30-day outcomes.'],['PASS','Table 8 columns (1)–(4)','Original estimates, market/two-way clustering and 999-draw market wild p-values.'],['PASS','Post-borrow flows and overlap','All requested horizons, all/sample vault supply and repayments; full-tail overlap correction.'],['ERROR FOUND','Original 80-event isolation statement','Two events lack prior168h;78 coverage-certified; old/new estimates retained.'],['ERROR FOUND','Original censoring/overlap boundary','21 tail threshold borrows change three next-borrow times, two horizon observations and overlap totals.'],['ERROR FOUND','Table 8 sample note','651 denotes complete duplication outcomes, not simply positive pre-event vault positions.'],['PARTIAL','Withdrawal spillovers','Both chains in observed windows; Base only ten vaults, not full universe.'],['PASS','Table 8 portable bundle','Original col(2)/80-event estimates and input hashes checked.'],['PASS','Full replay portable bundle','All 2,634 runs agree with archives; integer cash checks.'],['PASS WITH SCOPE','Current Word check','614 checked numeric cells, zero archived-source differences; ancillary labels/cells scope stated.'],['PASS','Manuscript preservation','Supplied document remains byte-identical.']]
    sections.append(table(pd.DataFrame(register,columns=['Status','Item','Evidence / limitation'])))
    sections.append('All delivery validation checks passed, including links, pinned input hashes, source-program paths and manuscript preservation; see [validation](logs/delivery_validation.json). Scripts and status logs are under [code](code/) and [logs](logs/). The top-level source-dependent rerun sequence is documented in [REPRODUCTION.md](REPRODUCTION.md); the two packages are separately portable. No missing analysis is represented by fabricated estimates, and no proposed correction has been silently applied to the manuscript.\n')
    (OUT/'DISCUSSANT_REPORT.md').write_text('\n'.join(sections))
    print('Report written',flush=True)

if __name__=='__main__':run()
